using attendence.Data;using attendence.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.Data.SqlClient;
namespace attendence.Controllers;
[Authorize(Roles="Administrator")]
public sealed class UserAccountsController(AccountRepository accounts,StudentRepository students,SchoolManagementRepository school,PasswordHasher<AppUser> hasher,ILogger<UserAccountsController> logger):Controller
{
 [HttpGet] public async Task<IActionResult> Index(CancellationToken ct){try{ViewBag.Accounts=await accounts.GetAccountsAsync(ct);ViewBag.Students=(await students.GetAllAsync(null,ct)).Where(x=>x.IsActive).ToList();ViewBag.Teachers=(await school.LoadAsync(ct)).Teachers.Where(x=>x.IsActive).ToList();return View(new UserAccountForm());}catch(SqlException ex){logger.LogError(ex,"Account management data failed");TempData["Error"]="Account management could not load. Check database setup.";ViewBag.Accounts=Array.Empty<UserAccountRow>();ViewBag.Students=Array.Empty<Student>();ViewBag.Teachers=Array.Empty<TeacherRow>();return View(new UserAccountForm());}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(UserAccountForm form,CancellationToken ct){if(form.Role is not ("Teacher" or "Student"))ModelState.AddModelError(nameof(form.Role),"Only teacher and student accounts can be created here.");if(form.Role=="Teacher"&&form.TeacherId is null)ModelState.AddModelError(nameof(form.TeacherId),"Choose a teacher profile.");if(form.Role=="Student"&&form.StudentId is null)ModelState.AddModelError(nameof(form.StudentId),"Choose a student profile.");if(form.Role=="Teacher")form.StudentId=null;if(form.Role=="Student")form.TeacherId=null;if(!ModelState.IsValid)return await IndexWithFormAsync(form,ct);var user=new AppUser{Email=form.Email.Trim(),Role=form.Role,StudentId=form.StudentId,TeacherId=form.TeacherId};user.PasswordHash=hasher.HashPassword(user,form.Password);try{await accounts.CreateAsync(user,ct);TempData["Success"]="Account created. The password was stored as a secure hash.";}catch(SqlException ex) when(ex.Number is 2601 or 2627){ModelState.AddModelError(nameof(form.Email),"An account already uses this email or that profile is linked to another account.");return await IndexWithFormAsync(form,ct);}catch(SqlException ex){logger.LogError(ex,"Account creation failed");TempData["Error"]="Account could not be created. Verify the selected profile and database schema.";}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Deactivate(int id,CancellationToken ct){try{var changed=await accounts.DeactivateAsync(id,ct);TempData[changed?"Success":"Error"]=changed?"Account deactivated.":"This administrator account cannot be deactivated here.";}catch(SqlException ex){logger.LogError(ex,"Account deactivation failed");TempData["Error"]="Account could not be deactivated.";}return RedirectToAction(nameof(Index));}
 private async Task<IActionResult> IndexWithFormAsync(UserAccountForm form,CancellationToken ct){await Index(ct);return View("Index",form);}
}
